#!/usr/bin/env python3
"""
Script to reproduce the KeyError in dask.config.rename
"""

import dask.config

def test_rename_keyerror():
    """Reproduce the KeyError that occurs when rename tries to delete a key that doesn't exist in exact form"""

    # Simulate the scenario where a key exists in underscore form but we're trying to delete hyphen form
    config = {
        'tick_maximum_delay': 0.1,  # Original key stored with underscore
        'other-config': 'value'
    }

    # Aliases that map hyphen form to new nested structure  
    aliases = {
        'tick-maximum-delay': 'distributed.scheduler.tick_maximum_delay',  # Note: hyphen form
    }

    print("Original config:", config)
    print("Aliases:", aliases)

    try:
        # This should fail with KeyError because 'tick-maximum-delay' doesn't exist 
        # in the config dict, but 'tick_maximum_delay' does
        dask.config.rename(aliases, config=config)
        print("Rename succeeded unexpectedly!")
        print("Final config:", config)
    except KeyError as e:
        print(f"KeyError reproduced: {e}")
        return True

    return False

def test_rename_with_canonical_fix():
    """Test that using canonical_name would fix the issue"""

    # Same setup as above
    config = {
        'tick_maximum_delay': 0.1,  # Original key stored with underscore
        'other-config': 'value'
    }

    aliases = {
        'tick-maximum-delay': 'distributed.scheduler.tick_maximum_delay',
    }

    print("\nTesting manual fix with canonical_name...")
    print("Original config:", config)

    # Manual implementation using canonical_name (what the fix should do)
    old = []
    new = {}
    for o, n in aliases.items():
        value = dask.config.get(o, None, config=config)
        if value is not None:
            old.append(o)
            new[n] = value

    print("Keys to rename:", old)
    print("New mappings:", new)

    # This is the current problematic part
    for k in old:
        try:
            del config[k]  # This will fail
            print(f"Successfully deleted '{k}'")
        except KeyError as e:
            print(f"KeyError when deleting '{k}': {e}")

            # Show what the canonical name would be
            canonical_k = dask.config.canonical_name(k, config)
            print(f"Canonical name for '{k}' would be '{canonical_k}'")
            if canonical_k in config:
                print(f"'{canonical_k}' exists in config: {config[canonical_k]}")

if __name__ == "__main__":
    print("=== Reproducing dask.config.rename KeyError ===")
    test_rename_keyerror()
    test_rename_with_canonical_fix()

