"""
Test script to verify the fix for dask.config.rename KeyError
"""

import dask.config

def test_current_rename_bug():
    """Test that demonstrates the current bug"""
    config = {'tick_maximum_delay': 0.1}
    aliases = {'tick-maximum-delay': 'distributed.scheduler.tick_maximum_delay'}

    try:
        dask.config.rename(aliases, config=config)
        print("ERROR: Should have raised KeyError!")
        return False
    except KeyError:
        print("✓ Confirmed: Current implementation raises KeyError")
        return True

def test_proposed_fix():
    """Test the proposed fix manually"""

    def fixed_rename(aliases, config=dask.config.config):
        """Fixed version of rename function"""
        old = []
        new = {}
        for o, n in aliases.items():
            value = dask.config.get(o, None, config=config)
            if value is not None:
                old.append(o)
                new[n] = value

        for k in old:
            # THE FIX: Use canonical_name when deleting
            canonical_k = dask.config.canonical_name(k, config)
            del config[canonical_k]

        dask.config.set(new, config=config)

    config = {'tick_maximum_delay': 0.1, 'untouched_key': 'keep_me'}
    aliases = {'tick-maximum-delay': 'distributed.scheduler.tick_maximum_delay'}

    print("Before fix:", config)
    try:
        fixed_rename(aliases, config=config)
        print("✓ Fixed version succeeded")
        print("After fix:", config)

        # Verify the transformation
        expected = {
            'untouched_key': 'keep_me',
            'distributed': {'scheduler': {'tick_maximum_delay': 0.1}}
        }
        if config == expected:
            print("✓ Config transformation is correct")
            return True
        else:
            print(f"✗ Config mismatch. Expected: {expected}, Got: {config}")
            return False
    except Exception as e:
        print(f"✗ Fixed version failed: {e}")
        return False

if __name__ == "__main__":
    print("=== Testing dask.config.rename fix ===")

    # Test current bug
    test_current_rename_bug()

    print()

    # Test proposed fix
    test_proposed_fix()

