        print("✓ Test 2 passed")
    else:
        print(f"✗ Test 2 failed. Expected: {expected2}")
        return False

    # Test case 3: No matching keys (should not fail)
    config3 = {'unrelated_key': 'value'}
    aliases3 = {'non-existent-key': 'somewhere.else.value'}

