#!/usr/bin/env python3

"""
Test edge cases to ensure we didn't break existing functionality.
"""

import warnings
from dataclasses import dataclass, field
from datetime import datetime
from mashumaro.config import BaseConfig
from mashumaro.jsonschema import build_json_schema


class CustomType:
    def __init__(self, value):
        self.value = value


def custom_serializer(value) -> str:
    """A custom serializer with return annotation."""
    return str(value)


def custom_serializer_no_annotation(value):
    """A custom serializer WITHOUT return annotation."""
    return str(value)


@dataclass
class TestWithAnnotation:
    field: CustomType

    class Config(BaseConfig):
        serialization_strategy = {
            CustomType: {"serialize": custom_serializer}
        }


@dataclass
class TestWithoutAnnotation:
    field: CustomType

    class Config(BaseConfig):
        serialization_strategy = {
            CustomType: {"serialize": custom_serializer_no_annotation}
        }


@dataclass
class TestDateTime:
    field: datetime

    class Config(BaseConfig):
        serialization_strategy = {
            datetime: {"serialize": datetime.timestamp}
        }


def test_case(name, dataclass_type, should_have_warning=False):
    print(f"\n--- Testing {name} ---")

    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")

        schema = build_json_schema(dataclass_type)
        field_property = schema.properties.get("field")
        print(f"Field schema: {field_property}")

        if w:
            for warning in w:
                print(f"Warning: {warning.message}")
                if should_have_warning:
                    print("✅ Expected warning generated")
                else:
                    print("❌ Unexpected warning")
        else:
            print("No warnings")
            if should_have_warning:
                print("❌ Expected warning was not generated")
            else:
                print("✅ No unexpected warnings")


def main():
    print("Testing edge cases...")

    # Test custom function WITH annotation (should work as before)
    test_case("Custom function with annotation", TestWithAnnotation, should_have_warning=False)

    # Test custom function WITHOUT annotation (should warn as before) 
    test_case("Custom function without annotation", TestWithoutAnnotation, should_have_warning=True)

    # Test datetime.timestamp (should warn as before since it has no return annotation)
    test_case("datetime.timestamp", TestDateTime, should_have_warning=True)


if __name__ == "__main__":
    main()

