    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")

        schema = build_json_schema(Foo)
        print("Generated JSON Schema:")
        print(schema.to_json())
        print()

        # Check warnings
        if w:
            print("❌ UNEXPECTED WARNINGS:")
            for warning in w:
                print(f"  {warning.message}")
        else:
            print("✅ No warnings generated!")

    # Validate the schema structure
    bar_property = schema.properties.get("bar")
    print(f"\nBar property schema details:")
    print(f"  Type: {bar_property.type}")

    # The fix should result in a proper string type
    if bar_property.type == JSONSchemaInstanceType.STRING:
        print("✅ SUCCESS: Bar property correctly identified as string type")
    else:
        print(f"❌ FAILURE: Expected string type, got {bar_property.type}")

    # Compare with expected output from issue description
