    # Test all basic types work correctly
    basic_types_tests = [
        (str, JSONSchemaInstanceType.STRING, "string"),
        (int, JSONSchemaInstanceType.INTEGER, "integer"), 
        (float, JSONSchemaInstanceType.NUMBER, "number"),
        (bool, JSONSchemaInstanceType.BOOLEAN, "boolean")
    ]

    all_passed = True
    for basic_type, expected_schema_type, type_name in basic_types_tests:
        @dataclass
        class TestClass:
            field: URL

            class Config(BaseConfig):
                serialization_strategy = {
                    URL: {"serialize": basic_type}
                }

        with warnings.catch_warnings(record=True) as w:
            warnings.simplefilter("always")
            test_schema = build_json_schema(TestClass)
            field_type = test_schema.properties["field"].type

            if field_type == expected_schema_type:
