"""
Comprehensive test to verify the JSON content type parser fix.
"""

import json
from msrest.pipeline.universal import RawDeserializer

def test_comprehensive():
    """Comprehensive test of the fix."""
    print("=== Comprehensive Test of JSON Content Type Parser ===\n")

    # Test data
    json_data = '{"message": "Hello World", "count": 42, "active": true}'

    # 1. Test existing supported content types (backward compatibility)
    print("1. Testing backward compatibility:")
    legacy_types = ['application/json', 'text/json']
    for content_type in legacy_types:
        try:
            result = RawDeserializer.deserialize_from_text(json_data, content_type)
            print(f"   ✓ {content_type}: SUCCESS")
        except Exception as e:
            print(f"   ✗ {content_type}: FAILED - {str(e)}")

    # 2. Test new +json pattern support
    print("\n2. Testing new +json pattern support:")
    plus_json_types = [
        'application/vnd.api+json',
        'application/hal+json',
        'application/problem+json',
        'application/ld+json',
        'application/vnd.collection+json',
        'application/calendar+json',
        'application/stix+json'
    ]
    for content_type in plus_json_types:
        try:
            result = RawDeserializer.deserialize_from_text(json_data, content_type)
            print(f"   ✓ {content_type}: SUCCESS")
        except Exception as e:
            print(f"   ✗ {content_type}: FAILED - {str(e)}")

    # 3. Test that non-JSON content types still fail appropriately
    print("\n3. Testing that non-JSON content types still fail:")
    non_json_types = [
        'application/xml',
        'text/plain',
        'application/octet-stream',
        'application/notjson',
        'application/prefix+notjson',
        'text/html+json',  # Not application/*
        'application/json+extra'  # +json not at end
    ]
    for content_type in non_json_types:
        try:
            result = RawDeserializer.deserialize_from_text(json_data, content_type)
            print(f"   ⚠ {content_type}: UNEXPECTED SUCCESS (should fail)")
        except Exception as e:
            if "Cannot deserialize content-type" in str(e) or "XML is invalid" in str(e):
                print(f"   ✓ {content_type}: CORRECTLY FAILED")
            else:
                print(f"   ? {content_type}: FAILED WITH UNEXPECTED ERROR - {str(e)}")

    # 4. Test edge cases
    print("\n4. Testing edge cases:")
    edge_cases = [
        ('application/+json', True),      # Minimal prefix
        ('application/a+json', True),     # Single char prefix
        ('application/very.long.prefix.with.dots+json', True),  # Complex prefix
    ]
    for content_type, should_succeed in edge_cases:
        try:
            result = RawDeserializer.deserialize_from_text(json_data, content_type)
            if should_succeed:
                print(f"   ✓ {content_type}: EXPECTED SUCCESS")
            else:
                print(f"   ⚠ {content_type}: UNEXPECTED SUCCESS")
        except Exception as e:
            if should_succeed:
                print(f"   ✗ {content_type}: UNEXPECTED FAILURE - {str(e)}")
            else:
                print(f"   ✓ {content_type}: EXPECTED FAILURE")

    print("\n=== Test Complete ===")

if __name__ == "__main__":
    test_comprehensive()

