"""Test edge cases for the Dict merge fix."""

from dataclasses import dataclass, field
from typing import Dict, List
from omegaconf import OmegaConf


@dataclass
class VariousDictTypes:
    str_dict: Dict[str, str] = field(default_factory=dict)
    int_dict: Dict[str, int] = field(default_factory=dict)
    list_dict: Dict[str, List[int]] = field(default_factory=dict)
    nested_dict: Dict[str, Dict[str, str]] = field(default_factory=dict)


def test_various_dict_types():
    """Test merging different typed dict fields."""
    cfg = OmegaConf.create({"data": VariousDictTypes()})
    print("Initial cfg:", cfg)

    # Test Dict[str, str]
    res1 = OmegaConf.merge(cfg, {"data": {"str_dict": {"key1": "val1"}}})
    assert res1.data.str_dict == {"key1": "val1"}
    print("✓ Dict[str, str] merge works")

    # Test Dict[str, int]
    res2 = OmegaConf.merge(cfg, {"data": {"int_dict": {"key1": 42}}})
    assert res2.data.int_dict == {"key1": 42}
    print("✓ Dict[str, int] merge works")

    # Test Dict[str, List[int]]
    res3 = OmegaConf.merge(cfg, {"data": {"list_dict": {"key1": [1, 2, 3]}}})
    assert res3.data.list_dict == {"key1": [1, 2, 3]}
    print("✓ Dict[str, List[int]] merge works")

    # Test Dict[str, Dict[str, str]]
    res4 = OmegaConf.merge(cfg, {"data": {"nested_dict": {"key1": {"subkey": "subval"}}}})
    assert res4.data.nested_dict == {"key1": {"subkey": "subval"}}
    print("✓ Dict[str, Dict[str, str]] merge works")


def test_multiple_keys():
    """Test merging multiple keys at once."""
    cfg = OmegaConf.create({"data": VariousDictTypes()})

    res = OmegaConf.merge(cfg, {
        "data": {
            "str_dict": {"key1": "val1", "key2": "val2"},
            "int_dict": {"num1": 10, "num2": 20}
        }
    })

    assert res.data.str_dict == {"key1": "val1", "key2": "val2"}
    assert res.data.int_dict == {"num1": 10, "num2": 20}
    print("✓ Multiple keys merge works")


if __name__ == "__main__":
    print("Testing various dict types...")
    try:
        test_various_dict_types()
        print("All dict type tests passed!")
    except Exception as e:
        print("FAILED:", e)
        import traceback
        traceback.print_exc()

    print("\nTesting multiple keys...")
    try:
        test_multiple_keys()
        print("Multiple keys test passed!")
    except Exception as e:
        print("FAILED:", e)
        import traceback
        traceback.print_exc()

