"""

from canvasapi.util import combine_kwargs

def test_original_issue():
    """Test the exact issue from the bug report."""
    print("=== Testing Original Issue ===")
    result = combine_kwargs(
        dict_list_dict={
            'key1': [
                {'subkey1a': 'value1a'},
                {'subkey1b': 'value1b'}
            ],
            'key2': [
                {'subkey2a': 'value2a'},
                {'subkey2b': 'value2b'}
            ]
        }
    )

    expected = [
        ('dict_list_dict[key1][][subkey1a]', 'value1a'),
        ('dict_list_dict[key1][][subkey1b]', 'value1b'),
        ('dict_list_dict[key2][][subkey2a]', 'value2a'),
        ('dict_list_dict[key2][][subkey2b]', 'value2b')
    ]

    print("Results:")
    for item in sorted(result):
        print(f"  {item}")

    print("\nValidation:")
    success = True
    for exp in expected:
        if exp in result:
            print(f"  ✓ Found: {exp}")
        else:
            print(f"  ✗ Missing: {exp}")
            success = False

    if success and len(result) == len(expected):
        print("  ✓ All expected items found and no extras")
    else:
        print(f"  ✗ Length mismatch: expected {len(expected)}, got {len(result)}")

    return success

def test_edge_cases():
    """Test various edge cases."""
    print("\n=== Testing Edge Cases ===")

    # Empty list
    result1 = combine_kwargs(
        empty_list_test={'key': []}
    )
    print(f"Empty list: {result1}")

    # Single item list
    result2 = combine_kwargs(
        single_item={'key': [{'subkey': 'value'}]}
    )
    print(f"Single item: {result2}")
    expected_single = [('single_item[key][][subkey]', 'value')]
    if expected_single[0] in result2:
        print("  ✓ Single item correct")
    else:
        print("  ✗ Single item incorrect")
        return False

    # Mixed types in same dict
    result3 = combine_kwargs(
        mixed={
            'list_key': [{'subkey': 'value'}],
            'dict_key': {'nested': 'value'},
            'simple': 'value'
        }
    )
    print(f"Mixed types: {result3}")

    # Check expected patterns
    patterns_found = 0
    for item in result3:
        if 'mixed[list_key][][subkey]' in item[0]:
            patterns_found += 1
        elif 'mixed[dict_key][nested]' in item[0]:
            patterns_found += 1
        elif ('mixed[simple]', 'value') == item:
            patterns_found += 1

    if patterns_found == 3:
        print("  ✓ Mixed types correct")
    else:
        print(f"  ✗ Mixed types incorrect: found {patterns_found}/3 patterns")
        return False

    return True

def test_backward_compatibility():
    """Ensure existing functionality still works."""
    print("\n=== Testing Backward Compatibility ===")

    # Direct list (should work as before)
    result1 = combine_kwargs(
        direct_list=[{'key1': 'val1'}, {'key2': 'val2'}]
