This test could be integrated into the main test suite.
"""

import unittest
from canvasapi.util import combine_kwargs


class TestCombineKwargsFix(unittest.TestCase):
    """Test cases for the combine_kwargs fix."""

    def test_dict_containing_list_of_dicts(self):
        """Test the specific issue: dictionary containing lists of dictionaries."""
        # This is the exact example from the GitHub issue
        result = combine_kwargs(
            dict_list_dict={
                'key1': [
                    {'subkey1a': 'value1a'},
                    {'subkey1b': 'value1b'}
                ],
                'key2': [
                    {'subkey2a': 'value2a'},
                    {'subkey2b': 'value2b'}
                ]
            }
        )

        # Should produce the correct format with [] right after the list key
        expected_items = {
            ('dict_list_dict[key1][][subkey1a]', 'value1a'),
            ('dict_list_dict[key1][][subkey1b]', 'value1b'),
            ('dict_list_dict[key2][][subkey2a]', 'value2a'),
            ('dict_list_dict[key2][][subkey2b]', 'value2b')
        }

        # Convert result to set for easier comparison
        result_set = set(result)

        # Check that all expected items are present
        self.assertEqual(len(result), 4)
        self.assertTrue(expected_items.issubset(result_set))

        # Verify the incorrect pattern is NOT present
        incorrect_patterns = [
            item for item in result 
            if item[0].endswith('[]') and '][' in item[0]
        ]
        self.assertEqual(len(incorrect_patterns), 0, 
                        f"Found incorrect patterns: {incorrect_patterns}")

    def test_backward_compatibility_direct_list(self):
        """Ensure direct lists still work as before."""
        result = combine_kwargs(
            list_dicts=[
                {
                    'l_d1a': 'val1a',
                    'l_d1b': 'val1b'
                },
                {
                    'l_d2a': 'val2a',
                    'l_d2b': 'val2b'
                }
            ]
        )

        expected_items = {
            ('list_dicts[][l_d1a]', 'val1a'),
            ('list_dicts[][l_d1b]', 'val1b'),
            ('list_dicts[][l_d2a]', 'val2a'),
            ('list_dicts[][l_d2b]', 'val2b')
        }

        result_set = set(result)
        self.assertTrue(expected_items.issubset(result_set))

    def test_mixed_scenarios(self):
        """Test mixed scenarios to ensure robustness."""
        result = combine_kwargs(
            mixed_scenario={
                'dict_list': [
                    {'key1': 'value1'},
                    {'key2': 'value2'}
                ],
                'simple_dict': {
                    'nested_key': 'nested_value'
                },
                'simple_value': 'simple'
            }
        )

        # Check all expected patterns are present
        result_set = set(result)

        # Dictionary containing list of dicts should use new format
        self.assertIn(('mixed_scenario[dict_list][][key1]', 'value1'), result_set)
        self.assertIn(('mixed_scenario[dict_list][][key2]', 'value2'), result_set)

        # Simple nested dict should use old format  
        self.assertIn(('mixed_scenario[simple_dict][nested_key]', 'nested_value'), result_set)

        # Simple values should work normally
        self.assertIn(('mixed_scenario[simple_value]', 'simple'), result_set)


if __name__ == '__main__':
    unittest.main()

