def _get_last_modified_time(self) -> float:
    """Get the most recent modified time out of all files being watched."""
    modification_times = []
    for path in self._paths:
        try:
            modification_times.append(os.stat(path).st_mtime)
        except FileNotFoundError:
            # File is temporarily missing (e.g., during vim save operations)
            # Treat as very old modification time so it doesn't affect the max
            modification_times.append(0.0)
    return max(modification_times, default=0)

