are incorrectly processed as outgoing relationships.
"""

import json
import tempfile
import os
from dbtmetabase.parsers.dbt_manifest import DbtManifestReader

def create_test_manifest():
    """Create a test manifest that demonstrates the issue."""

    # This simulates a simplified manifest.json structure
    manifest = {
        "nodes": {
            "model.test.customers": {
                "name": "customers",
                "schema": "public", 
                "database": "test",
                "resource_type": "model",
                "unique_id": "model.test.customers",
                "config": {"materialized": "table"},
                "columns": {
                    "customer_id": {
                        "name": "customer_id",
                        "description": "Primary key"
                    },
                    "name": {
                        "name": "name", 
                        "description": "Customer name"
                    }
                }
            },
            "model.test.orders": {
                "name": "orders",
                "schema": "public",
                "database": "test", 
                "resource_type": "model",
                "unique_id": "model.test.orders",
                "config": {"materialized": "table"},
                "columns": {
                    "order_id": {
                        "name": "order_id",
                        "description": "Primary key"
                    },
                    "customer_id": {
                        "name": "customer_id",
                        "description": "Foreign key to customers"
                    }
                }
            },
            # Relationship test: orders.customer_id references customers.customer_id
            "test.test.relationship_orders_customer_id_to_customers_customer_id": {
                "name": "relationship_orders_customer_id_to_customers_customer_id",
                "resource_type": "test",
                "test_metadata": {
                    "name": "relationships",
                    "kwargs": {
                        "field": "customer_id"
                    }
                },
                "depends_on": {
                    "nodes": [
                        "model.test.orders",      # Source model (orders)
                        "model.test.customers"    # Target model (customers) 
                    ]
                },
                "column_name": "customer_id"
            }
        },
        "sources": {},
        "child_map": {
            # When processing customers, we find the relationship test
            "model.test.customers": [
                "test.test.relationship_orders_customer_id_to_customers_customer_id"
            ],
            # When processing orders, we also find the same relationship test  
            "model.test.orders": [
                "test.test.relationship_orders_customer_id_to_customers_customer_id"
            ]
        }
    }

    return manifest

def test_relationship_processing():
    """Test how relationship tests are currently processed."""

    print("=== Testing Relationship Test Processing ===\n")

    # Create test manifest
    manifest = create_test_manifest()

    # Write manifest to temporary file
    with tempfile.NamedTemporaryFile(mode='w', suffix='.json', delete=False) as f:
        json.dump(manifest, f)
        manifest_path = f.name

    try:
        # Create reader for customers model
        print("Processing customers model...")
        reader = DbtManifestReader(manifest_path, "TEST", "PUBLIC")
        customers_models, _ = reader.read_models()

        # Find the customers model
        customers_model = None
        for model in customers_models:
            if model.name == "CUSTOMERS":
                customers_model = model
                break

        if customers_model:
            print(f"Customers model columns:")
            for col in customers_model.columns:
                print(f"  - {col.name}: fk_target_table={col.fk_target_table}")

            # Check if customer_id incorrectly gets FK designation
            customer_id_col = None
            for col in customers_model.columns:
                if col.name == "CUSTOMER_ID":
                    customer_id_col = col
                    break

            if customer_id_col and customer_id_col.fk_target_table:
                print(f"\n❌ BUG REPRODUCED: Customer ID incorrectly marked as FK pointing to {customer_id_col.fk_target_table}")
                print("   This is wrong - customer_id should be a PK, not FK!")
            else:
                print("\n✅ Customers model processed correctly - no incorrect FK assignments")

        print("\n" + "="*50 + "\n")

        # Create reader for orders model  
        print("Processing orders model...")
        reader2 = DbtManifestReader(manifest_path, "TEST", "PUBLIC")
        orders_models, _ = reader2.read_models()

        # Find the orders model
        orders_model = None
        for model in orders_models:
            if model.name == "ORDERS":
                orders_model = model
                break

        if orders_model:
            print(f"Orders model columns:")
            for col in orders_model.columns:
                print(f"  - {col.name}: fk_target_table={col.fk_target_table}")

            # Check if orders.customer_id correctly gets FK designation
            order_customer_id_col = None
            for col in orders_model.columns:
                if col.name == "CUSTOMER_ID":
                    order_customer_id_col = col
                    break

            if order_customer_id_col and order_customer_id_col.fk_target_table:
                print(f"\n✅ Orders customer_id correctly marked as FK pointing to {order_customer_id_col.fk_target_table}")
            else:
                print("\n❌ ERROR: Orders customer_id should be FK but isn't marked as such")

    finally:
        # Clean up temp file
        os.unlink(manifest_path)

if __name__ == "__main__":
    test_relationship_processing()

