#!/usr/bin/env python3
"""
Reproduction script for the optional argument omission issue in gql.

This script reproduces the KeyError when optional fields are omitted 
from input objects when using serialize_variables=True.
"""

from datetime import datetime
from typing import Any, Dict, Optional
from pathlib import Path
import tempfile

from gql import Client, gql
from gql.transport.requests import RequestsHTTPTransport
from gql.utilities import update_schema_scalars, serialize_value
from graphql import GraphQLScalarType, ValueNode, GraphQLSchema
from graphql.utilities import value_from_ast_untyped


def serialize_timestamp(value: Any) -> str:
    return value.isoformat()

def parse_timestamp_value(value: Any) -> datetime:
    return datetime.fromisoformat(value)

def parse_timestamp_literal(
    value_node: ValueNode, variables: Optional[Dict[str, Any]] = None
) -> datetime:
    ast_value = value_from_ast_untyped(value_node, variables)
    return parse_timestamp_value(ast_value)

TimestampScalar = GraphQLScalarType(
    name="timestamp",
    serialize=serialize_timestamp,
    parse_value=parse_timestamp_value,
    parse_literal=parse_timestamp_literal,
)


# Schema from the issue description
schema_str = """
scalar timestamp

type site_monitoring_acquisition_request {
  created_at: timestamp!
  updated_at: timestamp
}

input site_monitoring_acquisition_request_insert_input {
  created_at: timestamp!
  updated_at: timestamp
}

type mutation_root {
  insert_site_monitoring_acquisition_request(
    objects: [site_monitoring_acquisition_request_insert_input!]!
  ): site_monitoring_acquisition_request
}

schema {
  query: mutation_root
  mutation: mutation_root
}
"""


def test_direct_serialize_value():
    """Test the serialize_value function directly to isolate the issue"""
    print("=== Testing serialize_value directly ===")

    # First, let's parse the schema to get the input type
    from graphql import build_schema

    schema = build_schema(schema_str)
    update_schema_scalars(schema, [TimestampScalar])

    # Get the input type
    input_type = schema.type_map['site_monitoring_acquisition_request_insert_input']
    print(f"Input type: {input_type}")
    print(f"Fields: {list(input_type.fields.keys())}")

    # Test with all fields provided
    print("\n--- Test 1: All fields provided ---")
    try:
        models_full = [{
            "created_at": datetime.now(),
            "updated_at": datetime.now(),  # Provided
        }]

        result = serialize_value(input_type, models_full[0])
        print(f"Success: {result}")
    except Exception as e:
        print(f"Error: {e}")

    # Test with optional field omitted - this should trigger the KeyError
    print("\n--- Test 2: Optional field omitted (should fail) ---")
    try:
        models_partial = [{
            "created_at": datetime.now(),
            # "updated_at": datetime.now(),  # OMITTED - this causes the issue
        }]

        result = serialize_value(input_type, models_partial[0])
        print(f"Success: {result}")
    except Exception as e:
        print(f"Error: {type(e).__name__}: {e}")


def test_client_execute():
    """Test using the full client execution path"""
    print("\n\n=== Testing full client execution ===")

    # Create a mock transport that just prints the request
    class MockTransport:
        def execute(self, document, variable_values=None, operation_name=None, 
                   extra_args=None, upload_files=None):
            print(f"Mock transport received:")
            print(f"  Variable values: {variable_values}")
            # Return a mock result
            return {"data": {"insert_site_monitoring_acquisition_request": {"returning": [{"uuid": "test-uuid"}]}}}

    client = Client(transport=MockTransport(), schema=schema_str, serialize_variables=True)
    update_schema_scalars(client.schema, [TimestampScalar])

    models = [{
        "created_at": datetime.now(),
        # CANNOT BE OMITTED:
        # "updated_at": datetime.now(),
    }]

    try:
        result = client.execute(
            gql("""
                mutation insert_site_monitoring_acquisition_request(
                    $objects: [site_monitoring_acquisition_request_insert_input!]!
                ) {
                    insert_site_monitoring_acquisition_request(objects: $objects) {
                        returning {
                            uuid
                        }
                    }
                }
            """),
            variable_values={"objects": models},
        )
        print(f"Success: {result}")
    except Exception as e:
        print(f"Error: {type(e).__name__}: {e}")


if __name__ == "__main__":
    test_direct_serialize_value()
    test_client_execute()

