"""
Comprehensive test for the optional argument fix.
"""

from datetime import datetime
from typing import Any, Dict, Optional

from gql import Client, gql
from gql.utilities import serialize_value, update_schema_scalars
from graphql import GraphQLScalarType, ValueNode, GraphQLSchema, GraphQLInputObjectType, \
    GraphQLString, GraphQLInt, GraphQLInputField, GraphQLNonNull, build_schema
from graphql.utilities import value_from_ast_untyped


def serialize_timestamp(value: Any) -> str:
    return value.isoformat()

def parse_timestamp_value(value: Any) -> datetime:
    return datetime.fromisoformat(value)

def parse_timestamp_literal(
    value_node: ValueNode, variables: Optional[Dict[str, Any]] = None
) -> datetime:
    ast_value = value_from_ast_untyped(value_node, variables)
    return parse_timestamp_value(ast_value)

TimestampScalar = GraphQLScalarType(
    name="timestamp",
    serialize=serialize_timestamp,
    parse_value=parse_timestamp_value,
    parse_literal=parse_timestamp_literal,
)


def test_comprehensive_cases():
    """Test various scenarios with the fixed serialize_value function"""

    print("=== Comprehensive Test Cases ===")

    # Test 1: Simple case from the issue
    schema_str1 = """
scalar timestamp

input site_monitoring_acquisition_request_insert_input {
  created_at: timestamp!
  updated_at: timestamp
}

schema {
  query: QueryRoot
  mutation: MutationRoot
}

type QueryRoot {
  dummy: String
}

type MutationRoot {
  insert(data: site_monitoring_acquisition_request_insert_input): String
}
"""

    schema1 = build_schema(schema_str1)
    update_schema_scalars(schema1, [TimestampScalar])

    input_type1 = schema1.type_map['site_monitoring_acquisition_request_insert_input']

    print("\n--- Test 1: Original issue case ---")

    # With all fields
    data_full = {
        "created_at": datetime.now(),
        "updated_at": datetime.now(),
    }
    result = serialize_value(input_type1, data_full)
    print(f"All fields: Success - {result}")

    # With optional field omitted
    data_partial = {
        "created_at": datetime.now(),
        # updated_at omitted
    }
    result = serialize_value(input_type1, data_partial)
    print(f"Optional field omitted: Success - {result}")

    # Test 2: More complex nested input object
    print("\n--- Test 2: Nested input objects ---")

    nested_input = GraphQLInputObjectType(
        "NestedInput",
        {
            "required_field": GraphQLInputField(GraphQLNonNull(GraphQLString)),
            "optional_field": GraphQLInputField(GraphQLString),
            "another_optional": GraphQLInputField(GraphQLInt),
        }
    )

    # Full data
    nested_full = {
        "required_field": "test",
        "optional_field": "optional_value",
        "another_optional": 42,
    }
    result = serialize_value(nested_input, nested_full)
    print(f"Nested full: Success - {result}")

    # Partial data
    nested_partial = {
        "required_field": "test",
        # optional_field omitted
        # another_optional omitted
    }
    result = serialize_value(nested_input, nested_partial)
    print(f"Nested partial: Success - {result}")

    # Test 3: List of input objects
    print("\n--- Test 3: List of input objects ---")

    # List with mixed field presence
    list_data = [
        {
            "required_field": "item1",
            "optional_field": "present",
            "another_optional": 1,
        },
        {
            "required_field": "item2",
            # optional_field omitted
            "another_optional": 2,
        },
        {
            "required_field": "item3",
            # both optional fields omitted
        }
    ]

    from graphql import GraphQLList
    list_type = GraphQLList(nested_input)
    result = serialize_value(list_type, list_data)
    print(f"List of objects: Success - {result}")

    # Test 4: Explicit null values should still work
    print("\n--- Test 4: Explicit null values ---")

