"""
Test case for optional field omission in input objects.
This test verifies that optional fields can be omitted without causing KeyError.
"""

import pytest
from datetime import datetime
from typing import Any, Dict, Optional

from gql import Client, gql
from gql.utilities import serialize_value, update_schema_scalars
from graphql import GraphQLScalarType, ValueNode, build_schema


def serialize_timestamp(value: Any) -> str:
    return value.isoformat()

def parse_timestamp_value(value: Any) -> datetime:
    return datetime.fromisoformat(value)

def parse_timestamp_literal(
    value_node: ValueNode, variables: Optional[Dict[str, Any]] = None
) -> datetime:
    from graphql.utilities import value_from_ast_untyped
    ast_value = value_from_ast_untyped(value_node, variables)
    return parse_timestamp_value(ast_value)

TimestampScalar = GraphQLScalarType(
    name="timestamp",
    serialize=serialize_timestamp,
    parse_value=parse_timestamp_value,
    parse_literal=parse_timestamp_literal,
)


def test_serialize_value_optional_field_omission():
    """Test that optional fields can be omitted from input objects without KeyError."""

    schema_str = """
scalar timestamp

input TestInput {
  required_field: String!
  optional_field: String
  another_optional: Int
}

type Query {
  dummy: String
}

type Mutation {
  test(input: TestInput!): String
}
"""

    schema = build_schema(schema_str)
    update_schema_scalars(schema, [TimestampScalar])

    input_type = schema.type_map['TestInput']

    # Test with all fields present
    full_data = {
        "required_field": "test",
        "optional_field": "optional_value",
        "another_optional": 42,
    }
    result = serialize_value(input_type, full_data)
    expected_full = {
        "required_field": "test",
        "optional_field": "optional_value", 
        "another_optional": 42
    }
    assert result == expected_full

    # Test with some optional fields omitted
    partial_data = {
        "required_field": "test",
        # optional_field omitted
        "another_optional": 24,
    }
    result = serialize_value(input_type, partial_data)
    expected_partial = {
        "required_field": "test",
        "another_optional": 24
    }
    assert result == expected_partial

    # Test with all optional fields omitted
    minimal_data = {
        "required_field": "test",
        # both optional fields omitted
    }
    result = serialize_value(input_type, minimal_data)
    expected_minimal = {
        "required_field": "test"
    }
    assert result == expected_minimal

    # Test with explicit null values (should still be included)
    null_data = {
        "required_field": "test",
        "optional_field": None,  # Explicitly null
        # another_optional omitted
    }
    result = serialize_value(input_type, null_data)
    expected_null = {
        "required_field": "test",
        "optional_field": None
    }
    assert result == expected_null


def test_client_execute_with_optional_fields_omitted():
    """Test that client.execute works with omitted optional fields."""

    schema_str = """
scalar timestamp

input TestInput {
  required_field: String!
  optional_field: String
}

type Query {
  dummy: String
}

type Mutation {
  test(input: TestInput!): String
}
"""

    class MockTransport:
        def connect(self):
            pass

        def close(self):
            pass

        def execute(self, document, variable_values=None, operation_name=None, 
                   extra_args=None, upload_files=None):
            # Verify that omitted fields are not in the serialized variables
            input_data = variable_values.get('input', {})
            assert 'required_field' in input_data
            # optional_field should not be present if it was omitted
            # (this tests our fix)
            return {"data": {"test": "success"}}

    client = Client(transport=MockTransport(), schema=schema_str, serialize_variables=True)
    update_schema_scalars(client.schema, [TimestampScalar])

    # Execute with optional field omitted
    variables = {
        "input": {
            "required_field": "test_value",
            # optional_field omitted - this used to cause KeyError
        }
    }

    result = client.execute(
        gql("""
            mutation ($input: TestInput!) {
                test(input: $input)
            }
        """),
        variable_values=variables
    )

    assert result["data"]["test"] == "success"


if __name__ == "__main__":
    test_serialize_value_optional_field_omission()
    test_client_execute_with_optional_fields_omitted()
    print("All tests passed!")

