"""Comprehensive test to reproduce the PEPMASS string handling issue."""

import ast
from matchms.filtering.metadata_processing.interpret_pepmass import _interpret_pepmass_metadata, _get_mz_intensity_charge


def test_get_mz_intensity_charge_various_inputs():
    """Test _get_mz_intensity_charge with various inputs."""

    test_cases = [
        # Normal cases that should work
        (981.54, (981.54, None, None)),
        ((981.54,), (981.54, None, None)),
        ((981.54, 123.45), (981.54, 123.45, None)),
        ((981.54, 123.45, 1), (981.54, 123.45, 1)),

        # String representations that should be handled
        ("(981.54, None)", "ERROR"),  # This is the bug case
        ("(981.54, 123.45)", "ERROR"),  # This should also fail currently
        ("(981.54, 123.45, 1)", "ERROR"),  # This should also fail currently

        # Edge cases
        (None, (None, None, None)),
        ("", (None, None, None)),  # Should be handled by _convert_mz_or_intensity
    ]

    print("Testing _get_mz_intensity_charge function:")
    for i, (input_val, expected) in enumerate(test_cases):
        print(f"\nTest case {i+1}: {repr(input_val)}")
        try:
            result = _get_mz_intensity_charge(input_val)
            print(f"  Result: {result}")
            if expected != "ERROR":
                if result == expected:
                    print("  ✓ PASS")
                else:
                    print(f"  ✗ FAIL - Expected: {expected}")
            else:
                print("  ! Unexpected success - this case was expected to fail")
        except Exception as e:
            print(f"  Exception: {type(e).__name__}: {e}")
            if expected == "ERROR":
                print("  ✓ EXPECTED FAILURE")
            else:
                print(f"  ✗ UNEXPECTED FAILURE - Expected: {expected}")


def test_interpret_pepmass_metadata_with_strings():
    """Test _interpret_pepmass_metadata with string representations."""

    test_cases = [
        # Case from the bug report
        ({
            'pepmass': "(981.54, None)",
            'charge': 1
        }, "ERROR"),

        # Other string formats
        ({
            'pepmass': "(981.54, 123.45)",
            'charge': 1
        }, "ERROR"),

        ({
            'pepmass': "(981.54, 123.45, 1)",
            'charge': 2  # This should be overridden
        }, "ERROR"),
    ]

    print("\n\nTesting _interpret_pepmass_metadata function:")
    for i, (input_metadata, expected) in enumerate(test_cases):
        print(f"\nTest case {i+1}: pepmass={repr(input_metadata['pepmass'])}")
        try:
            result = _interpret_pepmass_metadata(input_metadata.copy())
            print(f"  Result keys: {list(result.keys())}")
            print(f"  precursor_mz: {result.get('precursor_mz')}")
            print(f"  precursor_intensity: {result.get('precursor_intensity')}")
            print(f"  charge: {result.get('charge')}")
            if expected == "ERROR":
                print("  ! Unexpected success - this case was expected to fail")
            else:
                print("  ✓ SUCCESS")
        except Exception as e:
            print(f"  Exception: {type(e).__name__}: {e}")
            if expected == "ERROR":
                print("  ✓ EXPECTED FAILURE")
            else:
                print(f"  ✗ UNEXPECTED FAILURE")


def test_with_ast_literal_eval():
    """Test if we can use ast.literal_eval to parse the string tuples."""

    string_tuples = [
        "(981.54, None)",
        "(981.54, 123.45)",
        "(981.54, 123.45, 1)",
        "981.54",  # Single value
    ]

    print("\n\nTesting ast.literal_eval approach:")
    for s in string_tuples:
        print(f"\nString: {repr(s)}")
        try:
            parsed = ast.literal_eval(s)
            print(f"  Parsed: {parsed} (type: {type(parsed)})")

            # Test our function with the parsed result
            result = _get_mz_intensity_charge(parsed)
            print(f"  _get_mz_intensity_charge result: {result}")

        except Exception as e:
            print(f"  Failed to parse: {type(e).__name__}: {e}")


if __name__ == "__main__":
    test_get_mz_intensity_charge_various_inputs()
    test_interpret_pepmass_metadata_with_strings()
    test_with_ast_literal_eval()

