    """Resource to get list of users."""

    @login_required
    def get(self):
        """Handles GET request to the resource.

        Returns:
            List of usernames
        """
        return self.to_json(User.query.all())

    @login_required
    def post(self):
        """Handles POST request to the resource for creating users.

        Returns:
            User object
        """
        if not current_user.admin:
            abort(HTTP_STATUS_CODE_FORBIDDEN, "User is not an admin.")

        form = request.json
        if not form:
            form = request.data

        username = form.get("username")
        password = form.get("password")

        if not username:
            abort(HTTP_STATUS_CODE_NOT_FOUND, "No username supplied.")

        user = User.get_or_create(username=username, name=username)
        if password:
            user.set_password(plaintext=password)
        db_session.add(user)
        db_session.commit()
        return self.to_json(user, status_code=HTTP_STATUS_CODE_OK)

