    print(f"DEBUG __getattr__: attr='{attr}', nested={getattr(self, 'nested', False)}, endpoint={getattr(self, 'endpoint', None)}")
    interface = self.interface
    original_attr = attr
    if getattr(self, 'nested', False):
        attr = "%s.%s" % (self.endpoint, attr)
        print(f"  Nested attr becomes: '{attr}'")

    submethod_exists = False
    submethod_match = attr + '.'
    matching_keys = []
    for key in interface.keys():
        if key.startswith(submethod_match):
            submethod_exists = True
            matching_keys.append(key)

    print(f"  Checking interface for '{attr}': {'found' if attr in interface else 'not found'}")
    print(f"  Submethod exists for '{attr}': {submethod_exists}")
    if matching_keys:
        print(f"    Matching keys: {matching_keys}")

    # Call original method - but with our fixed logic for this test
    interface = self.interface
    if getattr(self, 'nested', False):
        attr = "%s.%s" % (self.endpoint, original_attr)
    submethod_exists = False
    submethod_match = attr + '.'
    for key in interface.keys():
        if key.startswith(submethod_match):
            submethod_exists = True
            break
    # If this attribute path leads to sub-methods, treat it as a conduit endpoint path
    if attr not in interface and submethod_exists:
        return Resource(self.api, interface, attr, self.endpoint, nested=True)
    # If this is a known endpoint, treat it as such
    elif attr in interface:
        if getattr(self, 'nested', False):
            return Resource(self.api, interface[attr], attr, self.method)
        return Resource(self.api, interface[attr], attr, self.endpoint)
    # If it's a class attribute, return it (but only if it's not masking a conduit path)
    elif original_attr in getattr(self, '__dict__', {}):
        return getattr(self, original_attr)
    # Otherwise, treat as new endpoint
    else:
        interface[attr] = {}
        if getattr(self, 'nested', False):
            return Resource(self.api, interface[attr], attr, self.method)
        return Resource(self.api, interface[attr], attr, self.endpoint)

Resource.__getattr__ = debug_getattr

def debug_clean():
    """Debug with clean state."""

    # Create a Phabricator instance
    phab = Phabricator(username='test', certificate='test', host='http://localhost/api/')

    # Add test interfaces
    test_interfaces = {
        'almanac.device.search': {'description': 'Test device search', 'params': {}},
        'almanac.interface.search': {'description': 'Test interface search', 'params': {}},
        'almanac.interface.edit': {'description': 'Test interface edit', 'params': {}},
    }

    # Manually update the interface
    original_interface = phab.interface.copy()
    phab.interface.update(test_interfaces)

    print("=== Clean debugging - single access ===")

    print("\nAccessing phab.almanac.interface directly:")
