        print(f"Almanac endpoint: {almanac_resource.endpoint}")

        # Now access interface
        interface_resource = almanac_resource.interface
        print(f"Interface resource type: {type(interface_resource)}")

    except Exception as e:
        print(f"Error: {e}")
        import traceback
        traceback.print_exc()

    # Restore original interface and method
    phab.interface = original_interface
    Resource.__getattr__ = original_getattr

if __name__ == '__main__':
