#!/usr/bin/env python3
"""Test that FastAPI root_path still works after the fix."""

from starlette_exporter import PrometheusMiddleware, handle_metrics
from starlette.routing import Route
from starlette.responses import JSONResponse
from starlette.testclient import TestClient
from prometheus_client import generate_latest


def hello_endpoint(request):
    return JSONResponse({'message': 'Hello World'})


def metrics_endpoint(request):
    return JSONResponse({'metrics': generate_latest().decode()})


def test_fastapi_root_path():
    """Test FastAPI root_path compatibility."""
    try:
        from fastapi import FastAPI

        print("Testing FastAPI root_path compatibility")
        print("=" * 50)

        # Create FastAPI app with root_path set (like FastAPI docs suggest)
        app = FastAPI(root_path='/api')  # Set via FastAPI
        app.add_middleware(PrometheusMiddleware, filter_unhandled_paths=True)

        @app.get('/hello')
        def hello_handler():
            return {'msg': 'hello from FastAPI'}

        @app.get('/metrics')
        def metrics_handler():
            return JSONResponse({'metrics': generate_latest().decode()})

        # TestClient WITHOUT root_path (this simulates normal FastAPI usage)
        client = TestClient(app)

        print("Making request to '/api/hello' (FastAPI root_path='/api')")
        response = client.get('/api/hello')
        print(f"Response status: {response.status_code}")

        # Get metrics
        metrics_response = client.get('/metrics')
        metrics_data = metrics_response.json()['metrics']

        print("\nChecking if metrics were recorded...")

        # Look for metrics with the hello endpoint
        hello_metrics = []
        for line in metrics_data.split('\n'):
            if 'requests_total' in line and 'hello' in line:
                hello_metrics.append(line.strip())

        if hello_metrics:
            print("✅ SUCCESS: FastAPI root_path metrics working")
            for metric in hello_metrics:
                print(f"  {metric}")
            return True
        else:
            print("❌ FAILURE: FastAPI root_path metrics not working")
            return False

    except ImportError:
        print("FastAPI not available, skipping test")
        return True


if __name__ == "__main__":
    success = test_fastapi_root_path()
    exit(0 if success else 1)

