    @field
    def x(self):
        return 1

    @field
    def y(self):
        return 2


@attrs.define
class SmallItem:
    x: int


def test_working_case():
    """Test the working case - regular class with skip_nonitem_fields=True"""
    print("=== Testing Working Case ===")

    class SmallXPage(BigPage, Returns[SmallItem], skip_nonitem_fields=True):
        pass

    page = SmallXPage()
    print(f"page._skip_nonitem_fields: {page._skip_nonitem_fields}")  # Should be True

    # This should work
    try:
        item = asyncio.run(page.to_item())
        print(f"item: {item}")  # Should be SmallItem(x=1)
        print("✅ Working case succeeded!")
        return True
    except Exception as e:
        print(f"❌ Working case failed: {e}")
        return False


def test_broken_case():
    """Test the broken case - attrs class with skip_nonitem_fields=True"""
    print("\n=== Testing Broken Case ===")

    @attrs.define
    class SmallPage(BigPage, Returns[SmallItem], skip_nonitem_fields=True):
        params: PageParams

