        item = asyncio.run(page.to_item())
        print(f"   ❌ Unexpectedly succeeded: {item}")
        results.append(False)
    except Exception as e:
        print(f"   ✅ Correctly failed: {type(e).__name__}")
        results.append(True)

    # Test 2: Regular class with skip (should succeed)
    print("\n2. Regular class with skip_nonitem_fields=True (should succeed)")
    try:
