        results.append(False)
    except Exception as e:
        print(f"   ✅ Correctly failed: {type(e).__name__}")
        results.append(True)

    # Test 4: Attrs class with skip (THE MAIN FIX - should succeed)
    print("\n4. Attrs class with skip_nonitem_fields=True (MAIN FIX - should succeed)")
    try:
        @attrs.define
        class AttrsSuccess(BigPage, Returns[SmallItem], skip_nonitem_fields=True):
            extra_param: str = "test"

        page = AttrsSuccess(extra_param="test")
        print(f"   _skip_nonitem_fields: {page._skip_nonitem_fields}")
        item = asyncio.run(page.to_item())
        print(f"   ✅ Succeeded: {item}")
        results.append(item.x == 1 and not hasattr(item, 'y') and not hasattr(item, 'z'))
    except Exception as e:
        print(f"   ❌ Unexpectedly failed: {e}")
        results.append(False)

    # Test 5: Attrs class with explicit False (should fail)
    print("\n5. Attrs class with skip_nonitem_fields=False (should fail)")
    try:
        @attrs.define
        class AttrsExplicitFalse(BigPage, Returns[SmallItem], skip_nonitem_fields=False):
            extra_param: str = "test"

        page = AttrsExplicitFalse(extra_param="test")
        print(f"   _skip_nonitem_fields: {page._skip_nonitem_fields}")
        item = asyncio.run(page.to_item())
        print(f"   ❌ Unexpectedly succeeded: {item}")
        results.append(False)
    except Exception as e:
        print(f"   ✅ Correctly failed: {type(e).__name__}")
        results.append(True)

    # Test 6: Perfect match (no skipping needed)
    print("\n6. Perfect match scenario (should succeed)")
    try:
        @attrs.define
        class PerfectMatch(BigPage, Returns[BigItem]):
            extra_param: str = "test"

        page = PerfectMatch(extra_param="test")
        print(f"   _skip_nonitem_fields: {page._skip_nonitem_fields}")
        item = asyncio.run(page.to_item())
        print(f"   ✅ Succeeded: {item}")
