def __recoverable(
    self,
    response: Optional[Union[ConnectionError, Response]],
    url: str,
    request,
    counter: int = 1,
):
    msg = str(response)
    if isinstance(response, ConnectionError):
        logging.warning(
            f"Got ConnectionError [{response}] errno:{response.errno} on {request} {url}\n{vars(response)}\n{response.__dict__}"
        )
    if isinstance(response, Response):
        if response.status_code in [502, 503, 504]:
            # 502, 503, 504 can be recoverable on Jira server overload
            msg = f"{response.status_code} {response.reason}"
        elif response.status_code == 429:
            # 429 rate limiting is recoverable with backoff
            msg = f"{response.status_code} {response.reason}"
        elif response.status_code == 401:
            # 401 UNAUTHORIZED still randomly returned by Atlassian Cloud as of 2017-01-16
            # 2019-07-25: Disabled recovery for 401
            return False
        elif not (
            response.status_code == 200
            and len(response.content) == 0
            and "X-Seraph-LoginReason" in response.headers
            and "AUTHENTICATED_FAILED" in response.headers["X-Seraph-LoginReason"]
        ):
            return False
        else:
            msg = "Atlassian's bug https://jira.atlassian.com/browse/JRA-41559"

    # Handle Retry-After header for 429 responses
    retry_after = 0
    if isinstance(response, Response) and response.status_code == 429:
        retry_after_header = response.headers.get("Retry-After")
        if retry_after_header:
            try:
                retry_after = int(retry_after_header)
            except (ValueError, TypeError):
                # If Retry-After is not an integer, it might be an HTTP-date
                # For simplicity, we'll ignore non-integer values
                pass

    # Exponential backoff with full jitter.
    base_delay = min(self.max_retry_delay, 10 * 2**counter) * random.random()
    delay = max(base_delay, retry_after)
    logging.warning(
        "Got recoverable error from %s %s, will retry [%s/%s] in %ss. Err: %s"
        % (request, url, counter, self.max_retries, delay, msg)
    )
    if isinstance(response, Response):
        logging.debug("response.headers: %s", response.headers)
        logging.debug("response.body: %s", response.content)
    time.sleep(delay)
    return True

