"""Debug script to understand DvcException behavior."""

from dvc.exceptions import DvcException

try:
    try:
        raise ValueError("Original error message")
    except ValueError as e:
        cause_exception = e
        raise DvcException("Higher level error", cause=e)
except DvcException as exc:
    print("Exception str():", str(exc))
    print("Exception repr():", repr(exc))
    print("Exception type:", type(exc))
    print("Exception cause:", exc.cause)
    print("Exception cause type:", type(exc.cause))
    print("Cause str():", str(exc.cause))
    if hasattr(exc, 'cause_tb') and exc.cause_tb:
        print("Cause traceback:", exc.cause_tb)
    else:
        print("No cause traceback")

    # Walk the chain
    current = exc
    level = 0
    while current:
        print(f"Level {level}: {type(current).__name__}: {str(current)}")
        if hasattr(current, 'cause') and current.cause:
            current = current.cause
            level += 1
        else:
            break

