def _description(message):
    exception = sys.exc_info()[1]

    if exception and message:
        description = '{message} - {exception}'
    elif exception:
        description = '{exception}'
    elif message:
        description = '{message}'

    return description.format(message=message, exception=_format_exception(exception))


def _format_exception(exception):
    """Format exception including chained causes."""
    if not exception:
        return ''

    # If it's not a DvcException or has no cause, return normal string representation
    if not hasattr(exception, 'cause') or not exception.cause:
        return str(exception)

    # Build the full chain of exceptions
    messages = []
    current = exception

    # Traverse the cause chain
    while current:
        msg = str(current)
        if msg:  # Only add non-empty messages
            messages.append(msg)

        # Move to the cause if it's a DvcException with a cause
        if hasattr(current, 'cause') and current.cause:
            current = current.cause
        else:
            current = None

    # Join all messages with appropriate separator
    return ': '.join(messages)

