class TypedBuiltinBinaryOp(TypedOpBase):
    __slots__ = ()
    opclass = "BinaryOp"

    def __call__(
        self, left, right=None, *, require_monoid=None, left_default=None, right_default=None
    ):
        if left_default is not None or right_default is not None:
            if (
                left_default is None
                or right_default is None
                or require_monoid is not None
                or right is not None
                or not isinstance(left, InfixExprBase)
                or left.method_name != "ewise_add"
            ):
                raise TypeError(
                    "Specifying `left_default` or `right_default` keyword arguments implies "
                    "performing `ewise_union` operation with infix notation.\n"
                    "There is only one valid way to do this:\n\n"
                    f">>> {self}(x | y, left_default=0, right_default=0)\n\nwhere x and y "
                    "are Vectors or Matrices, and left_default and right_default are scalars."
                )
            return left.left.ewise_union(left.right, self, left_default, right_default)
        if require_monoid is not None:
            if right is not None:
                raise TypeError(
                    f"Bad keyword argument `require_monoid=` when calling {self!r}.\n"
                    "require_monoid keyword may only be used when performing an ewise_add.\n"
                    "Perhaps you meant `out=`?"
                )
            from ..matrix import Matrix, TransposedMatrix
            from ..vector import Vector

            if output_type(left) not in {Vector, Matrix, TransposedMatrix}:
                raise TypeError(
                    f"Bad type when calling {self!r}.\n"
                    "    - Expected type: Vector, Matrix, TransposedMatrix.\n"
                    f"    - Got: {type(left)}.\n"
                    "Keyword arguments `require_monoid` and `out` are only valid for binary methods."
                )
            return left.ewise_add(left, self, require_monoid=require_monoid)
        if right is None:
            # binary_op(A & B), binary_op(A | B), binary_op(A @ B)
            if not isinstance(left, InfixExprBase):
                raise TypeError(
                    f"Bad type when calling {self!r}.\n"
                    f"    - Got: {type(left)}.\n"
                    "Expected an infix expression, such as `A & B` or `A | B`"
                )
            method_name = left.method_name
            if method_name == "ewise_add":
                return left.left.ewise_add(left.right, self)
            elif method_name == "ewise_mult":
                return left.left.ewise_mult(left.right, self)
            elif method_name == "mxm":
                return left.left.mxm(left.right, self)
            elif method_name == "mxv":
                return left.left.mxv(left.right, self)
            elif method_name == "vxm":
                return left.left.vxm(left.right, self)
            elif method_name == "kronecker":
                return left.left.kronecker(left.right, self)
            else:
                return getattr(left.left, method_name)(left.right, self)
        # binary_op(A, B)
        from ..matrix import Matrix, TransposedMatrix
        from ..vector import Vector

        if output_type(left) not in {Vector, Matrix, TransposedMatrix} or output_type(
            right
        ) not in {Vector, Matrix, TransposedMatrix}:
            raise TypeError(
                f"Bad types when calling {self!r}.  Got types: {type(left)}, {type(right)}.\n"
                "Expected an infix expression or ewise_* or mx* or vxm or kronecker methods."
            )
        return left.ewise_mult(right, self)


