def pydecimal(self, left_digits=None, right_digits=None, positive=False,
              min_value=None, max_value=None):

    if left_digits is not None and left_digits < 0:
        raise ValueError(
            'A decimal number cannot have less than 0 digits in its '
            'integer part')
    if right_digits is not None and right_digits < 0:
        raise ValueError(
            'A decimal number cannot have less than 0 digits in its '
            'fractional part')
    if left_digits == 0 and right_digits == 0:
        raise ValueError(
            'A decimal number cannot have less than 0 digits in total')
    if None not in (min_value, max_value) and min_value > max_value:
        raise ValueError('Min value cannot be greater than max value')
    if None not in (min_value, max_value) and min_value == max_value:
        raise ValueError('Min and max value cannot be the same')
    if positive and min_value is not None and min_value <= 0:
        raise ValueError(
            'Cannot combine positive=True with negative or zero min_value')

    # Make sure at least either left or right is set
    if left_digits is None and right_digits is None:
        # Default behavior - choose reasonable defaults
        left_digits = self.random_int(1, 10)
        right_digits = self.random_int(0, 10)

    # If only one side is set, choose reasonable default for other side
    if (left_digits is None) ^ (right_digits is None):
        if left_digits is None:
            left_digits = max(1, 10 - right_digits)
        else:
            right_digits = max(0, 10 - left_digits)

    # Handle min/max value constraints
    if (min_value is not None) or (max_value is not None):
        # Generate within the specified range
        if min_value is None:
            min_value = -10 ** left_digits if not positive else 0
        if max_value is None:
            max_value = 10 ** left_digits

        if min_value > max_value:
            raise ValueError('Min value cannot be greater than max value')

        # Generate a random integer within the range
        left_number = self._safe_random_int(min_value, max_value, positive)
        # Convert to string to handle decimal part correctly
        left_str = str(abs(left_number))
        if len(left_str) > left_digits and left_digits is not None:
            # Truncate to fit within left_digits
            left_str = left_str[:left_digits]
            left_number = int(left_str) * (-1 if left_number < 0 else 1)

        # Generate fractional part
        if right_digits > 0:
            right_number = self.random_number(right_digits)
            sign = '-' if left_number < 0 and left_number != 0 else ('-' if positive is False and left_number == 0 else '')
            result_str = f'{sign}{abs(left_number)}.{right_number}'
        else:
            sign = '-' if left_number < 0 else ('' if not positive else '+')
            result_str = f'{sign}{abs(left_number)}'

        return Decimal(result_str)
    else:
        # No min/max constraints - generate freely
        sign = '+' if positive else self.random_element(('+', '-'))
        left_number = self.random_number(left_digits)

        if right_digits > 0:
            right_number = self.random_number(right_digits)
            result_str = f'{sign}{left_number}.{right_number}'
        else:
            result_str = f'{sign}{left_number}'

        result = Decimal(result_str)

        # Handle positive zero case
        if positive and result == 0:
            if right_digits > 0:
                # Create a small positive decimal
                result_str = '0.' + '0' * (right_digits - 1) + '1'
                result = Decimal(result_str)

        return result

