#!/usr/bin/env python3

"""Analyze what the actual issue might be with url_prefix path parameters"""

from flask import Flask
from flask_smorest import Api, Blueprint


def test_without_manual_parameters():
    """Test what happens when we DON'T manually document parameters"""
    app = Flask(__name__)
    app.config.update({
        'API_TITLE': 'Test API',
        'API_VERSION': 'v1',
        'OPENAPI_VERSION': '3.0.2',
    })

    api = Api(app)

    # Create blueprint with path parameters in url_prefix - NO manual documentation
    blueprint = Blueprint(
        'Media',
        __name__,
        url_prefix='/brands/<int:brand_id>/media',
    )

    @blueprint.route('/<int:item_id>')
    def get_media(brand_id, item_id):
        """Get media item for a brand"""
        return {'brand_id': brand_id, 'item_id': item_id}

    api.register_blueprint(blueprint)

    # Generate spec
    spec = api.spec.to_dict()

    print("WITHOUT manual parameter documentation:")
    print("=" * 50)
    path_key = "/brands/{brand_id}/media/{item_id}"
    if path_key in spec["paths"]:
        parameters = spec["paths"][path_key].get("parameters", [])
        print(f"Found {len(parameters)} parameters:")
        for param in parameters:
            print(f"  - {param}")
    else:
        print("Path not found!")


def test_with_partial_manual_parameters():
    """Test what happens when we only document SOME parameters"""
    app = Flask(__name__)
    app.config.update({
        'API_TITLE': 'Test API',
        'API_VERSION': 'v1',
        'OPENAPI_VERSION': '3.0.2',
    })

    api = Api(app)

    # Create blueprint with path parameters in url_prefix
    blueprint = Blueprint(
        'Media',
        __name__,
        url_prefix='/brands/<int:brand_id>/media',
    )

    @blueprint.route('/<int:item_id>', parameters=[
        # ONLY document item_id, not brand_id
        {
            'name': 'item_id', 
            'in': 'path',
            'description': 'The media item identifier',
            'required': True,
            'schema': {'type': 'integer'}
        }
    ])
    def get_media(brand_id, item_id):
        """Get media item for a brand"""
        return {'brand_id': brand_id, 'item_id': item_id}

    api.register_blueprint(blueprint)

    # Generate spec
    spec = api.spec.to_dict()

    print("\nWITH partial manual parameter documentation:")
    print("=" * 50)
