#!/usr/bin/env python

"""
Additional edge case tests for the dict_merge fix.
"""

import select
from rollbar.lib import dict_merge


def test_different_pickle_errors():
    """Test that different kinds of unpicklable objects are handled"""
    print("Testing different unpicklable objects...")

    # Test with select.epoll
    class WithEpoll:
        def __init__(self):
            self.epoll = select.epoll()
            self.data = "test"

    # Test with file object
    class WithFile:
        def __init__(self):
            self.file = open(__file__, 'r')
            self.data = "test"

    # Test with lambda (not picklable)
    class WithLambda:
        def __init__(self):
            self.func = lambda x: x
            self.data = "test"

    test_cases = [
        ("epoll object", WithEpoll()),
        ("lambda object", WithLambda()),
    ]

    # Close file to avoid resource warning
    with open(__file__, 'r') as f:
        class WithFile:
            def __init__(self):
                self.file = f
                self.data = "test"
        test_cases.append(("file object", WithFile()))

    all_passed = True
    for name, obj in test_cases:
        try:
            dict_a = {'existing': 'data'}
            dict_b = {'problematic': obj}

            result = dict_merge(dict_a, dict_b)
            print(f"  ✅ {name}: SUCCESS - {result['problematic']}")
        except Exception as e:
            print(f"  ❌ {name}: FAILED - {e}")
            all_passed = False

    return all_passed


def test_nested_unpicklable_objects():
    """Test deeply nested structures with unpicklable objects"""
    print("\nTesting nested unpicklable objects...")

    class UnpicklableObject:
        def __init__(self):
            self.epoll = select.epoll()
            self.nested = {'deep': {'deeper': 'value'}}

    try:
        dict_a = {
            'level1': {
                'level2': {
                    'existing': 'data'
                }
            }
        }

        dict_b = {
            'level1': {
                'level2': {
                    'unpicklable': UnpicklableObject()
                },
                'level2_new': 'new_data'
            },
            'top_level': 'value'
        }

        result = dict_merge(dict_a, dict_b)
        print("  ✅ Nested merge: SUCCESS")
        print(f"     Result contains: {list(result.keys())}")
        print(f"     Unpicklable replaced with: {result['level1']['level2']['unpicklable']}")
        return True
    except Exception as e:
        print(f"  ❌ Nested merge: FAILED - {e}")
        import traceback
        traceback.print_exc()
        return False


def test_regular_objects_still_work():
    """Test that regular (picklable) objects still work normally"""
    print("\nTesting that regular objects still work...")

    try:
        dict_a = {
            'string': 'value1',
            'nested': {'num': 1}
        }

        dict_b = {
            'string': 'value2',  # Should overwrite
            'nested': {'num': 2, 'new': 'data'},  # Should merge
            'list': [1, 2, 3],
            'dict': {'a': 'b'}
        }

        result = dict_merge(dict_a, dict_b)

        expected = {
            'string': 'value2',
            'nested': {'num': 2, 'new': 'data'},
            'list': [1, 2, 3],
            'dict': {'a': 'b'}
        }

        if result == expected:
            print("  ✅ Regular objects: SUCCESS")
            return True
        else:
            print(f"  ❌ Regular objects: WRONG RESULT")
            print(f"     Got: {result}")
            print(f"     Expected: {expected}")
            return False
    except Exception as e:
        print(f"  ❌ Regular objects: FAILED - {e}")
        return False


def test_other_type_errors_still_raised():
    """Test that non-pickle TypeErrors are still raised"""
    print("\nTesting that other TypeErrors are still raised...")

    # This should still raise the original TypeError, not be caught by our handler
    try:
        # Create a dict merge scenario that would cause a different TypeError
        dict_a = {'key': 'value'}
        # Pass a non-dict as second argument - this should raise TypeError but not about pickling
        result = dict_merge(dict_a, "not a dict")
        print("  ✅ Non-dict handling: SUCCESS (returned as-is)")
        return True
    except TypeError as e:
        if "can't pickle" in str(e):
            print(f"  ❌ Non-dict handling: INCORRECTLY CAUGHT PICKLE ERROR - {e}")
            return False
        else:
            print(f"  ✅ Non-dict handling: CORRECTLY RAISED OTHER TYPEERROR - {e}")
            return True
    except Exception as e:
        print(f"  ❌ Non-dict handling: UNEXPECTED ERROR - {e}")
        return False


if __name__ == "__main__":
    print("Testing edge cases for dict_merge fix...")
    print("=" * 50)

    tests = [
        test_different_pickle_errors(),
        test_nested_unpicklable_objects(), 
        test_regular_objects_still_work(),
        test_other_type_errors_still_raised()
    ]

    print("\n" + "=" * 50)
    if all(tests):
        print("✅ ALL EDGE CASE TESTS PASSED!")
    else:
        print("❌ SOME EDGE CASE TESTS FAILED!")
        for i, result in enumerate(tests, 1):
            status = "PASS" if result else "FAIL"
            print(f"  Test {i}: {status}")

