    if not isinstance(b, dict):
        return b

    result = a
    for k, v in b.items():
        if k in result and isinstance(result[k], dict):
            result[k] = dict_merge(result[k], v)
        else:
            try:
                result[k] = copy.deepcopy(v)
            except TypeError as e:
                # Handle unpicklable objects (e.g., select.epoll) gracefully
                # Still allow error reporting to continue by using a safe representation
                if "can't pickle" in str(e) or "cannot pickle" in str(e):
                    result[k] = '<Unpicklable object of type: %s>' % type(v).__name__
                else:
                    # Re-raise if it's a different kind of TypeError
                    raise
            except Exception as e:
                # Handle any other deepcopy-related exceptions gracefully
                result[k] = '<Unserializable object of type: %s, error: %s>' % (type(v).__name__, str(e))

    return result

