#!/usr/bin/env python

"""
Final verification that the exact issue from the bug report is fixed.
This simulates the Tornado + Rollbar scenario described in the issue.
"""

import rollbar
import sys
import select


def simulate_tornado_exception_with_epoll():
    """
    Simulate the exact scenario from the issue:
    Tornado HTTPError with request objects containing epoll
    """
    print("Simulating Tornado scenario with epoll objects...")

    # Initialize rollbar like in the issue
    rollbar.init('test_token', 'production', handler='blocking')

    # Create a request-like object that contains epoll (like Tornado might have)
    class TornadoLikeRequest:
        def __init__(self):
            # This simulates what Tornado might have internally
            self.connection = type('Connection', (), {
                'stream': type('Stream', (), {
                    'io_loop': type('IOLoop', (), {
                        '_impl': select.epoll()  # This is the problematic unpicklable object
                    })()
                })()
            })()
            self.headers = {'User-Agent': 'test-client'}
            self.method = 'GET'
            self.uri = '/test'

    # Create payload data that might contain unpicklable objects
    request_obj = TornadoLikeRequest()

    # This simulates the kind of payload_data that might cause issues
    payload_data = {
        'request': request_obj,
        'internal': {
            'loop': select.epoll(),  # Another unpicklable object
            'data': 'some info'
        }
    }

    try:
        # Simulate the HTTP 500 error from the traceback
        raise Exception("HTTP 500: Internal Server Error")
    except Exception:
        exc_info = sys.exc_info()

        try:
            # This is the call that was failing in the original issue
            uuid = rollbar.report_exc_info(
                exc_info=exc_info,
                request=request_obj,
                payload_data=payload_data
            )

            print(f"✅ SUCCESS: Error reported successfully with UUID: {uuid}")
            print("✅ No more 'can't pickle select.epoll objects' error!")
            return True

        except TypeError as e:
            if "can't pickle" in str(e):
                print(f"❌ FAILED: Still getting pickle error: {e}")
                return False
            else:
                print(f"❌ FAILED: Different TypeError: {e}")
                return False
        except Exception as e:
            # Other exceptions are OK - the key is no pickle error
            if "can't pickle" not in str(e):
                print(f"✅ SUCCESS: Error reported (other expected error: {type(e).__name__})")
                return True
            else:
                print(f"❌ FAILED: Still getting pickle error: {e}")
                return False


def test_message_reporting_with_unpicklable_data():
    """Test report_message with unpicklable objects too"""
    print("\nTesting report_message with unpicklable objects...")

    class RequestWithEpoll:
        def __init__(self):
            self.epoll_obj = select.epoll()
            self.data = {'secret': 'value'}

    request_obj = RequestWithEpoll()

    try:
        uuid = rollbar.report_message(
            message="Got an IOError in the main loop",
            level="warning", 
            request=request_obj,
            payload_data={'custom': {'epoll': select.epoll()}}
        )
        print(f"✅ SUCCESS: Message reported successfully with UUID: {uuid}")
        return True
    except TypeError as e:
        if "can't pickle" in str(e):
            print(f"❌ FAILED: Still getting pickle error: {e}")
            return False
        else:
            print(f"❌ FAILED: Different TypeError: {e}")
            return False
    except Exception as e:
        if "can't pickle" not in str(e):
            print(f"✅ SUCCESS: Message reported (other expected error: {type(e).__name__})")
            return True
        else:
            print(f"❌ FAILED: Still getting pickle error: {e}")
            return False


if __name__ == "__main__":
    print("Final verification of the Rollbar unpicklable objects fix")
    print("=" * 60)
    print("This reproduces the EXACT scenario from the GitHub issue:")
    print("- Tornado-like request objects with epoll")
    print("- report_exc_info and report_message calls")
    print("- Payload data containing unpicklable objects")
    print("=" * 60)

    test1 = simulate_tornado_exception_with_epoll()
    test2 = test_message_reporting_with_unpicklable_data()

    print("\n" + "=" * 60)
    if test1 and test2:
        print("🎉 ISSUE COMPLETELY FIXED!")
        print("Rollbar can now handle unpicklable objects gracefully")
        print("Errors are reported instead of silently failing")
        sys.exit(0)
    else:
        print("❌ ISSUE NOT FULLY RESOLVED")
        sys.exit(1)

