def _parse_datepart(args: t.List) -> exp.Expression:
    """
    Parse DATEPART function call into an Extract expression.
    DATEPART(quarter, date) -> EXTRACT(quarter FROM date)
    """
    # DATEPART has arguments in order: (date_part, date_expression)
    # EXTRACT has the same conceptual structure
    assert len(args) == 2
    return exp.Extract(this=args[0], expression=args[1])

